proc onCommitNeeded*(self: CompositorController,
                     handler: EventHandler[CompositorController, WinRtObject]): EventRegistrationToken {.discardable.} =
  ## Windows.UI.Composition.Core.CompositorController.add_CommitNeeded
  ## The token is what `removeCommitNeeded` takes.
  withIface(self.p, ICompositorController, it):
    proc shim(a0: pointer, a1: pointer) =
      handler(borrow[CompositorController](a0), borrow[WinRtObject](a1))
    let cb = newDelegate(IID_TypedEventHandler_2_CompositorController_Object, shim, event = true)
    try:
      it.call(ICompositorController_add_CommitNeeded, cb, result.addr)
    finally:
      release(cb)

